package netproxy

import (
	"bufio"
	"bytes"
	"context"
	"crypto/tls"
	"encoding/base64"
	"errors"
	"fmt"
	"io"
	"net"
	"net/http"
	"net/url"
	"time"
)

// maxConnectAnswer caps what is read while waiting for the answer to CONNECT: a
// proxy that never ends its header cannot make the check buffer without bound.
const maxConnectAnswer = 64 << 10

// Dialer opens TLS connections along the path an https request would take. The
// zero value follows the proxy environment variables.
type Dialer struct {
	// Proxy picks the proxy; nil means FromEnvironment.
	Proxy Selector
	// DialContext opens the TCP connection (to the proxy, or to the target when
	// direct); nil means (&net.Dialer{}).DialContext.
	DialContext func(ctx context.Context, network, addr string) (net.Conn, error)
	// ProxyTLSConfig configures TLS to an https:// proxy; nil means system roots.
	ProxyTLSConfig *tls.Config
}

// DialTLS connects to hostport (the port is required) the way an https request
// to it would travel, then completes the handshake with cfg (ServerName
// defaults to the host). ctx bounds the whole: proxy dial, CONNECT, handshake.
//
// A failure of the proxy step is a *Error; a failure of the target itself (its
// handshake, its certificate) is returned as it would be without a proxy. The
// returned connection owns the tunnel: closing it closes the socket.
func (d Dialer) DialTLS(ctx context.Context, hostport string, cfg *tls.Config) (*tls.Conn, error) {
	host, _, err := net.SplitHostPort(hostport)
	if err != nil {
		return nil, err
	}
	sel := d.Proxy
	if sel == nil {
		sel = FromEnvironment
	}
	proxy, err := sel(&url.URL{Scheme: "https", Host: hostport})
	if err != nil {
		return nil, &Error{Step: StepSelect, Err: err}
	}
	if proxy != nil && proxy.Scheme != "http" && proxy.Scheme != "https" {
		return nil, &Error{Proxy: proxy.Host, Step: StepScheme, Err: errors.New(proxy.Scheme)}
	}

	conn, err := d.tunnel(ctx, proxy, hostport)
	if err != nil {
		return nil, err
	}

	tc := tls.Client(conn, targetConfig(cfg, host))
	if err := tc.HandshakeContext(ctx); err != nil {
		_ = conn.Close()
		return nil, err
	}
	_ = conn.SetDeadline(time.Time{})
	return tc, nil
}

// tunnel returns a connection to hostport: direct when proxy is nil, otherwise
// through proxy by CONNECT. One deadline, ctx's, covers every step; on failure
// the connection is closed. The deadline is left set so the caller's handshake
// stays under it.
func (d Dialer) tunnel(ctx context.Context, proxy *url.URL, hostport string) (net.Conn, error) {
	dial := d.DialContext
	if dial == nil {
		dial = (&net.Dialer{}).DialContext
	}
	if proxy == nil {
		conn, err := dial(ctx, "tcp", hostport)
		if err != nil {
			return nil, err
		}
		if dl, ok := ctx.Deadline(); ok {
			_ = conn.SetDeadline(dl)
		}
		return conn, nil
	}

	addr := proxyAddr(proxy)
	raw, err := dial(ctx, "tcp", addr)
	if err != nil {
		return nil, &Error{Proxy: addr, Step: StepDial, Err: err}
	}
	if dl, ok := ctx.Deadline(); ok {
		_ = raw.SetDeadline(dl)
	}
	// A cancellation unblocks the reads and writes below by closing the socket.
	stop := context.AfterFunc(ctx, func() { _ = raw.Close() })
	conn, perr := d.connect(ctx, raw, proxy, addr, hostport)
	if perr != nil {
		stop()
		return nil, perr
	}
	if !stop() {
		// The cancellation fired after the CONNECT succeeded: the socket is closed.
		_ = conn.Close()
		return nil, &Error{Proxy: addr, Step: StepConnect, Err: ctx.Err()}
	}
	return conn, nil
}

// connect runs TLS to the proxy when it is https://, then the CONNECT exchange,
// on conn. It closes conn on failure.
func (d Dialer) connect(ctx context.Context, conn net.Conn, proxy *url.URL, addr, hostport string) (net.Conn, *Error) {
	fail := func(step Step, status int, err error) (net.Conn, *Error) {
		_ = conn.Close()
		if errors.Is(err, net.ErrClosed) && ctx.Err() != nil {
			err = ctx.Err() // our own AfterFunc closed it: the cause is the context's
		}
		return nil, &Error{Proxy: addr, Step: step, StatusCode: status, Err: err}
	}

	if proxy.Scheme == "https" {
		cfg := &tls.Config{}
		if d.ProxyTLSConfig != nil {
			cfg = d.ProxyTLSConfig.Clone()
		}
		if cfg.ServerName == "" {
			cfg.ServerName = proxy.Hostname()
		}
		tc := tls.Client(conn, cfg)
		if err := tc.HandshakeContext(ctx); err != nil {
			return fail(StepProxyTLS, 0, err)
		}
		conn = tc
	}

	if _, err := io.WriteString(conn, connectRequest(proxy.User, hostport)); err != nil {
		return fail(StepConnect, 0, err)
	}
	br := bufio.NewReader(io.LimitReader(conn, maxConnectAnswer))
	resp, err := http.ReadResponse(br, &http.Request{Method: http.MethodConnect})
	if err != nil {
		return fail(StepConnect, 0, err)
	}
	// The body of a CONNECT answer is the tunnel; it is not read or closed here.
	if resp.StatusCode != http.StatusOK {
		return fail(StepConnect, resp.StatusCode, nil)
	}
	if n := br.Buffered(); n > 0 {
		// Bytes read past the header belong to the tunnel; give them back first.
		peeked, _ := br.Peek(n)
		return &bufferedConn{Conn: conn, r: io.MultiReader(bytes.NewReader(bytes.Clone(peeked)), conn)}, nil
	}
	return conn, nil
}

// bufferedConn is a net.Conn whose reads start with bytes already taken off it.
type bufferedConn struct {
	net.Conn
	r io.Reader
}

func (c *bufferedConn) Read(p []byte) (int, error) { return c.r.Read(p) }

// connectRequest is the CONNECT request for hostport, with Basic credentials
// from user when the proxy URL carries any.
func connectRequest(user *url.Userinfo, hostport string) string {
	req := fmt.Sprintf("CONNECT %s HTTP/1.1\r\nHost: %s\r\n", hostport, hostport)
	if user != nil {
		password, _ := user.Password()
		cred := base64.StdEncoding.EncodeToString([]byte(user.Username() + ":" + password))
		req += "Proxy-Authorization: Basic " + cred + "\r\n"
	}
	return req + "\r\n"
}

// proxyAddr is the proxy's host:port, without userinfo, with the scheme's
// default port when the URL has none.
func proxyAddr(proxy *url.URL) string {
	if proxy.Port() != "" {
		return proxy.Host
	}
	port := "80"
	if proxy.Scheme == "https" {
		port = "443"
	}
	return net.JoinHostPort(proxy.Hostname(), port)
}

// targetConfig is a copy of cfg (or a fresh config) that verifies host unless
// cfg names another server.
func targetConfig(cfg *tls.Config, host string) *tls.Config {
	c := &tls.Config{}
	if cfg != nil {
		c = cfg.Clone()
	}
	if c.ServerName == "" {
		c.ServerName = host
	}
	return c
}
package netproxy

import (
	"context"
	"errors"
	"fmt"
	"net"
	"net/http"
)

// Step names the stage of the proxy path that failed.
type Step string

const (
	// StepSelect: the proxy setting is invalid.
	StepSelect Step = "select"
	// StepDial: the proxy cannot be reached.
	StepDial Step = "dial"
	// StepProxyTLS: TLS to an https:// proxy failed.
	StepProxyTLS Step = "proxy-tls"
	// StepConnect: CONNECT was refused, unreadable, or unanswered.
	StepConnect Step = "connect"
	// StepScheme: the proxy scheme is not supported (socks5).
	StepScheme Step = "scheme"
)

// Error is a failure at the proxy step of a connection, as opposed to a failure
// of the target itself. Proxy is host:port, never a userinfo.
type Error struct {
	// Proxy is the proxy's host:port.
	Proxy string
	// Step is where the proxy path failed.
	Step Step
	// StatusCode is the proxy's answer to CONNECT, 0 when it never gave one.
	StatusCode int
	// Err is the underlying cause, if any.
	Err error
}

// Error implements error. The text is built from the step, the status code and
// the cause's kind, never from the proxy's own words (a proxy is not trusted to
// phrase a message shown to the user): a refused CONNECT shows the standard
// reason phrase of its code.
func (e *Error) Error() string {
	switch e.Step {
	case StepSelect:
		return "proxy: invalid proxy setting: " + causeText(e.Err)
	case StepScheme:
		return "proxy: scheme " + causeText(e.Err) + " is not supported by the SSL check"
	case StepDial:
		return "proxy: cannot reach " + e.Proxy + ": " + causeText(e.Err)
	case StepProxyTLS:
		return "proxy: TLS to " + e.Proxy + " failed: " + causeText(e.Err)
	}
	if e.StatusCode != 0 {
		return fmt.Sprintf("proxy: CONNECT refused (%d %s)", e.StatusCode, http.StatusText(e.StatusCode))
	}
	if isTimeout(e.Err) {
		return "proxy: no answer from " + e.Proxy + " (timeout)"
	}
	return "proxy: unreadable answer to CONNECT from " + e.Proxy
}

// causeText is err's text, empty for a nil cause.
func causeText(err error) string {
	if err == nil {
		return ""
	}
	return err.Error()
}

// isTimeout reports whether err is a deadline or a network timeout.
func isTimeout(err error) bool {
	var ne net.Error
	return errors.Is(err, context.DeadlineExceeded) || (errors.As(err, &ne) && ne.Timeout())
}

// Unwrap returns the underlying cause.
func (e *Error) Unwrap() error { return e.Err }

package netproxy

import (
	"context"
	"errors"
	"testing"
)

func TestStepValues(t *testing.T) {
	tests := []struct {
		step Step
		want string
	}{
		{StepSelect, "select"},
		{StepDial, "dial"},
		{StepProxyTLS, "proxy-tls"},
		{StepConnect, "connect"},
		{StepScheme, "scheme"},
	}
	for _, tt := range tests {
		if string(tt.step) != tt.want {
			t.Errorf("step %q, want %q", tt.step, tt.want)
		}
	}
}

// TestErrorText pins the exact sentences the UI will show (Rule 129). In
// StepConnect, the status code decides "refused"; without one, a timeout cause
// is "no answer" and any other cause is "unreadable".
func TestErrorText(t *testing.T) {
	boom := errors.New("boom")
	tests := []struct {
		name string
		err  *Error
		want string
	}{
		{"refused 403", &Error{Proxy: "proxy.corp:3128", Step: StepConnect, StatusCode: 403},
			"proxy: CONNECT refused (403 Forbidden)"},
		{"refused 407", &Error{Proxy: "proxy.corp:3128", Step: StepConnect, StatusCode: 407},
			"proxy: CONNECT refused (407 Proxy Authentication Required)"},
		{"refused 502 with a cause", &Error{Proxy: "proxy.corp:3128", Step: StepConnect, StatusCode: 502, Err: boom},
			"proxy: CONNECT refused (502 Bad Gateway)"},
		{"no answer", &Error{Proxy: "proxy.corp:3128", Step: StepConnect, Err: context.DeadlineExceeded},
			"proxy: no answer from proxy.corp:3128 (timeout)"},
		{"unreadable", &Error{Proxy: "proxy.corp:3128", Step: StepConnect, Err: boom},
			"proxy: unreadable answer to CONNECT from proxy.corp:3128"},
		{"unreachable", &Error{Proxy: "proxy.corp:3128", Step: StepDial, Err: boom},
			"proxy: cannot reach proxy.corp:3128: boom"},
		{"proxy TLS", &Error{Proxy: "proxy.corp:3128", Step: StepProxyTLS, Err: boom},
			"proxy: TLS to proxy.corp:3128 failed: boom"},
		{"invalid setting", &Error{Step: StepSelect, Err: boom},
			"proxy: invalid proxy setting: boom"},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := tt.err.Error(); got != tt.want {
				t.Fatalf("Error() = %q, want %q", got, tt.want)
			}
		})
	}
}

func TestErrorUnwrap(t *testing.T) {
	boom := errors.New("boom")
	var err error = &Error{Proxy: "proxy.corp:3128", Step: StepDial, Err: boom}
	if !errors.Is(err, boom) {
		t.Error("errors.Is does not reach the cause")
	}
	if got := (&Error{Step: StepConnect, StatusCode: 403}).Unwrap(); got != nil {
		t.Errorf("Unwrap() = %v, want nil without a cause", got)
	}
}
